-- mod-temucraft-merchants: Craftsman's Writs and the supply factions (Azeroth Commerce Authority 2233, Durotar Supply and
-- Logistics 2234). Writs 601710+ start daily quests: bring the crafted item to the faction's quartermaster for
-- reputation, Merchant's Favor (601700) and money. Re-runnable.
SET @Favor := 601700;
DELETE FROM `item_template` WHERE `entry` = @Favor OR `entry` BETWEEN 601710 AND 601969;
DELETE FROM `quest_template` WHERE `ID` BETWEEN 601710 AND 601969;
DELETE FROM `creature_questender` WHERE `quest` BETWEEN 601710 AND 601969;

DELETE FROM `creature` WHERE `guid` BETWEEN 9200160 AND 9200163;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 601971 AND 601974;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 601971 AND 601974;
DELETE FROM `npc_vendor` WHERE `entry` IN (601972, 601974);
-- Looks borrowed from existing traders: human vendors for the Authority, a goblin and an orc for the Horde
